<!doctype html><html lang="<?= esc(service('request')->getLocale(),'attr') ?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= esc(lang('Pharmacy.labels')) ?></title><style>body{font:14px Arial,sans-serif;color:#17252b;padding:24px}.label{max-width:420px;border:1px solid #aaa;padding:20px;margin:16px 0;break-inside:avoid}.directions{font-size:16px;white-space:pre-wrap}.muted{color:#53606b;font-size:12px}@media print{button{display:none}body{padding:0}.label{border-color:#000}}</style></head><body><button type="button" onclick="window.print()"><?= esc(lang('Pharmacy.labels')) ?> / Print</button>
<?php $identity=(new \App\Services\ReceiptBrandingService())->get(); foreach ($items as $item): ?>
<article class="label"><strong><?= esc($identity['store_name']) ?></strong><p class="muted"><?= esc($sale['invoice_no'].' · '.$sale['sold_at']) ?></p><h2><?= esc($item['description']) ?></h2><p><?= esc($item['quantity'].' '.$item['unit_label']) ?></p>
<?php if ($prescription): ?><p><?= esc($prescription['patient_name']) ?></p><?php foreach ($prescription['items'] as $line): if ((int)$line['product_id'] !== (int)$item['product_id']) continue; ?><p class="directions"><?= esc($line['directions']) ?></p><?php if(!empty($line['route_of_administration'])): ?><p><?= esc('Recorded route: '.$line['route_of_administration']) ?></p><?php endif; ?><?php endforeach; ?><p class="muted"><?= esc($prescription['prescriber'].' · #'.$prescription['id']) ?></p><?php endif; ?>
<?php $lots=db_connect()->table('stock_movements m')->select('b.batch_no,b.expiry_date')->join('product_batches b','b.id=m.batch_id')->where('m.ref_type','sale')->where('m.ref_id',$sale['id'])->where('m.product_id',$item['product_id'])->groupBy('b.id'); if(db_connect()->tableExists('pharmacy_opened_packs')) $lots->select('o.use_by AS opened_use_by')->join('pharmacy_opened_packs o','o.batch_id=b.id','left'); $lots=$lots->get()->getResultArray(); foreach($lots as $lot): ?><p class="muted"><?= esc(lang('Pharmacy.batch_no').': '.$lot['batch_no'].' · '.lang('Pharmacy.expiry_date').': '.$lot['expiry_date']) ?></p><?php endforeach; ?></article>
<?php endforeach; ?></body></html>
